		if err != nil {
			return c.Status(500).JSON(fiber.Map{"message": "Internal server error"})
		}

		return c.Status(200).JSON(fiber.Map{"secret": secret})
	})

	log.Fatal(app.Listen("0.0.0.0:5000"))
